import type { ContractStatus, ContractType } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';

interface ContractStatusEntry {
  name: string;
  variant: BadgeVariants;
}

export const contractStatusConfig: Record<ContractStatus, ContractStatusEntry> = {
  pending: { name: 'Awaiting Signatures', variant: 'info' },
  active: { name: 'Signed', variant: 'success' },
  failed: { name: 'Signing Error', variant: 'destructive' },
  terminated: { name: 'Terminated', variant: 'default' },
};

export const contractStatusItems: SelectItem<ContractStatus>[] = Object.entries(contractStatusConfig).map(
  ([value, { name }]) => ({ value: value as ContractStatus, name })
);

const defaultContractStatus: ContractStatusEntry = { name: '', variant: 'default' };

export function getContractStatus(status: ContractStatus): ContractStatusEntry {
  return contractStatusConfig[status] ?? { ...defaultContractStatus, name: snakeCaseToCapitalizedCase(status) };
}

export function getContractStatusLabel(
  status: ContractStatus,
  contractType: ContractType,
  signedByAdmin: boolean | null,
  signedByCanvasser: boolean
): ContractStatusEntry {
  if (status !== 'pending') {
    return contractStatusConfig[status] ?? { ...defaultContractStatus, name: snakeCaseToCapitalizedCase(status) };
  }
  if (contractType === 'w9') {
    return signedByCanvasser
      ? { name: 'Processing', variant: 'info' }
      : { name: 'Awaiting Canvasser', variant: 'info' };
  }
  if (signedByAdmin && !signedByCanvasser) {
    return { name: 'Awaiting Canvasser', variant: 'info' };
  }
  if (!signedByAdmin && signedByCanvasser) {
    return { name: 'Awaiting Admin', variant: 'info' };
  }
  return contractStatusConfig.pending;
}
